// ==============================================================================
// 1. EXTRACCIÓN DUX: VENTAS DEL MES CERRADO & HISTÓRICO COMPARATIVO
// ==============================================================================

const DUX_TOKEN = 'vmkdwI9GaPx96GigvTpUI4gjBFAnQoGyDKRV1HuWO4LNZ3HOyvkA9YtxFVbZSNYo';
const ENTERPRISE_ID = 2224;

// Determinar mes cerrado y nuevo mes
const now = new Date();
let year = now.getFullYear();
let month = now.getMonth(); // 0 a 11 (mes anterior si hoy es día 1)
if (month === 0) {
  month = 12;
  year = year - 1;
}
const targetPeriod = `${year}-${String(month).padStart(2, '0')}`;
const fDesde = `${year}-${String(month).padStart(2, '0')}-01`;
const lastDay = new Date(year, month, 0).getDate();
const fHasta = `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

// Mes nuevo que arranca
let nextYear = year;
let nextMonth = month + 1;
if (nextMonth > 12) {
  nextMonth = 1;
  nextYear++;
}
const nextPeriod = `${nextYear}-${String(nextMonth).padStart(2, '0')}`;

// Fechas del mismo mes en el año anterior (2025)
const pastYear = year - 1;
const fDesdePastClosed = `${pastYear}-${String(month).padStart(2, '0')}-01`;
const fHastaPastClosed = `${pastYear}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;

const lastDayNextPast = new Date(pastYear, nextMonth, 0).getDate();
const fDesdePastNext = `${pastYear}-${String(nextMonth).padStart(2, '0')}-01`;
const fHastaPastNext = `${pastYear}-${String(nextMonth).padStart(2, '0')}-${String(lastDayNextPast).padStart(2, '0')}`;

const delay = ms => new Promise(res => setTimeout(res, ms));

async function fetchSucursalSales(sucId, dDesde, dHasta) {
  let all = [];
  let offset = 0;
  const limit = 50;
  while (true) {
    let res = null;
    let attempts = 0;
    while (attempts < 3 && !res) {
      try {
        res = await helpers.httpRequest({
          method: 'GET',
          url: 'https://erp.duxsoftware.com.ar/WSERP/rest/services/facturas',
          qs: {
            idEmpresa: ENTERPRISE_ID,
            idSucursal: sucId,
            fechaDesde: dDesde,
            fechaHasta: dHasta,
            limit,
            offset
          },
          headers: { authorization: DUX_TOKEN },
          json: true,
          timeout: 25000
        });
      } catch (e) {
        attempts++;
        if (attempts < 3) await delay(1500);
      }
    }
    const results = res?.results || [];
    all.push(...results);
    if (results.length < limit) break;
    offset += limit;
    await delay(300);
  }
  return all;
}

// 1. Extraer ventas mes cerrado actual (2026)
const tomFacturas = await fetchSucursalSales(2, fDesde, fHasta);
const maschFacturas = await fetchSucursalSales(3, fDesde, fHasta);

// 2. Extraer ventas históricas del año anterior (para calcular salto estacional real)
let saltoEstacionalTom = 1.15; // default seguro
let saltoEstacionalMasch = 1.15;

try {
  const tomPastClosed = await fetchSucursalSales(2, fDesdePastClosed, fHastaPastClosed);
  const tomPastNext = await fetchSucursalSales(2, fDesdePastNext, fHastaPastNext);
  const netPastClosed = tomPastClosed.reduce((acc, i) => acc + (Number(i.total) || 0) * (i.tipo_comp?.toUpperCase().includes('NC') ? -1 : 1), 0);
  const netPastNext = tomPastNext.reduce((acc, i) => acc + (Number(i.total) || 0) * (i.tipo_comp?.toUpperCase().includes('NC') ? -1 : 1), 0);
  if (netPastClosed > 0 && netPastNext > 0) {
    saltoEstacionalTom = Math.max(1.0, Math.min(1.5, netPastNext / netPastClosed));
  }
} catch(e) {}

// Procesar comprobantes actuales por vendedora
function processComprobantes(list) {
  const byVend = {};
  let totBruto = 0, totNC = 0;
  list.forEach(inv => {
    if (inv.anulada_boolean === true || inv.anulada === 'S') return;
    const tipo = (inv.tipo_comp || '').toUpperCase();
    const total = Number(inv.total) || 0;
    const esNC = tipo.includes('CREDITO') || tipo.includes('NC');
    const vId = String(inv.id_vendedor || '');
    if (!byVend[vId]) byVend[vId] = { bruto: 0, nc: 0, neta: 0 };
    if (esNC) {
      byVend[vId].nc += total;
      totNC += total;
    } else {
      byVend[vId].bruto += total;
      totBruto += total;
    }
  });
  Object.keys(byVend).forEach(k => {
    byVend[k].neta = byVend[k].bruto - byVend[k].nc;
  });
  return { byVend, totBruto, totNC, totNeta: totBruto - totNC };
}

return [{
  json: {
    periodo: targetPeriod,
    nextPeriod,
    saltoEstacionalTom,
    saltoEstacionalMasch,
    tom: processComprobantes(tomFacturas),
    masch: processComprobantes(maschFacturas)
  }
}];

const duxData = $('1. Extraer y Depurar Ventas Dux').first().json;
const horasApp = $('2. Leer Horas Reales Trabajadas (App)').all().map(i => i.json);
const objetivosPrev = $input.all().map(i => i.json);

const periodo = duxData.periodo;
const nextPeriod = duxData.nextPeriod;
const tom = duxData.tom;
const masch = duxData.masch;

// 1. LIQUIDACIÓN DEL MES CERRADO (Tabla Oficial 12 Columnas)
const objTomLocal = objetivosPrev.find(o => o.sucursal_codigo === 'TOM' && o.colab_id === 'TOTAL_LOCAL') || {};
const objMaschLocal = objetivosPrev.find(o => o.sucursal_codigo === 'MASCHWITZ' && o.colab_id === 'TOTAL_LOCAL') || {};
const metaTomN1 = Number(objTomLocal.objetivo_nivel_1) || 35000000;
const metaTomN2 = Number(objTomLocal.objetivo_nivel_2) || 42000000;
const metaMaschN1 = Number(objMaschLocal.objetivo_nivel_1) || 18000000;
const metaMaschN2 = Number(objMaschLocal.objetivo_nivel_2) || 21600000;

const liquidaciones = [];

const staffTom = [
  { vId: '1705102', colab_id: 'c-sofi', nombre: 'Sofía Barrientos', rol: 'Encargada' },
  { vId: '2907849', colab_id: 'c-esme', nombre: 'Esme Galarza', rol: 'Semi-Encargada' },
  { vId: '19950294', colab_id: 'c-cande', nombre: 'Candela Almiron', rol: 'Vendedora' },
  { vId: '19950328', colab_id: 'c-anto', nombre: 'Antonella Bustamante', rol: 'Vendedora' },
  { vId: '8662462', colab_id: 'c-martu', nombre: 'Martina Pinto', rol: 'Vendedora' }
];

staffTom.forEach(s => {
  const vData = tom.byVend[s.vId] || { bruto: 0, nc: 0, neta: 0 };
  const obj = objetivosPrev.find(o => o.sucursal_codigo === 'TOM' && o.colab_id === s.colab_id) || {};
  const metaPrevista = Number(obj.objetivo_nivel_1) || 0;
  const metaN2 = Number(obj.objetivo_nivel_2) || 0;
  let porcAlcance = metaPrevista > 0 ? (vData.neta / metaPrevista) * 100 : 0;
  let porcComis = 0, montoComis = 0, montoPlusCaja = 0;

  if (s.rol === 'Encargada') {
    porcAlcance = (tom.totNeta / metaTomN1) * 100;
    porcComis = tom.totNeta >= metaTomN2 ? 0.30 : (tom.totNeta >= metaTomN1 ? 0.20 : 0.10);
    montoComis = Math.round(tom.totNeta * (porcComis / 100));
  } else if (s.rol === 'Semi-Encargada') {
    porcComis = vData.neta >= metaN2 ? 0.90 : (vData.neta >= metaPrevista ? 0.60 : 0.30);
    montoComis = Math.round(vData.neta * (porcComis / 100));
    const porcPlus = tom.totNeta >= metaTomN2 ? 0.15 : (tom.totNeta >= metaTomN1 ? 0.10 : 0.05);
    montoPlusCaja = Math.round(tom.totNeta * (porcPlus / 100));
  } else {
    porcComis = vData.neta >= metaN2 ? 0.90 : (vData.neta >= metaPrevista ? 0.60 : 0.30);
    montoComis = Math.round(vData.neta * (porcComis / 100));
  }

  liquidaciones.push({
    periodo,
    sucursal_codigo: 'TOM',
    colab_id: s.colab_id,
    nombre: s.nombre,
    rol: s.rol,
    venta_bruta: vData.bruto,
    notas_credito: vData.nc,
    venta_neta: vData.neta,
    objetivo_previsto: metaPrevista,
    porc_alcance: Math.round(porcAlcance * 100) / 100,
    porc_comision: porcComis,
    monto_comision: montoComis,
    monto_plus_caja: montoPlusCaja,
    monto_pozo: 0,
    total_liquidado: montoComis + montoPlusCaja,
    estado_premio: porcAlcance >= 95 ? `⭐ Estrella del Mes (${Math.round(porcAlcance)}%)` : 'Desempeño estándar',
    estado: 'borrador'
  });
});

const staffMasch = [
  { vId: '11956305', colab_id: 'c-flavia', nombre: 'Flavia Gómez', rol: 'Encargada' },
  { vId: '5171913', colab_id: 'c-juli', nombre: 'Julieta Vera', rol: 'Vendedora' },
  { vId: '3988841', colab_id: 'c-cami', nombre: 'Camila Vera', rol: 'Vendedora' },
  { vId: '8662462', colab_id: 'c-martu_masch', nombre: 'Martina Pinto (Maschwitz)', rol: 'Vendedora' }
];

staffMasch.forEach(s => {
  const vData = masch.byVend[s.vId] || { bruto: 0, nc: 0, neta: 0 };
  const obj = objetivosPrev.find(o => o.sucursal_codigo === 'MASCHWITZ' && o.colab_id === s.colab_id) || {};
  const metaPrevista = Number(obj.objetivo_nivel_1) || 0;
  const metaN2 = Number(obj.objetivo_nivel_2) || 0;
  let porcAlcance = metaPrevista > 0 ? (vData.neta / metaPrevista) * 100 : 0;
  let porcComis = 0, montoComis = 0;

  if (s.rol === 'Encargada') {
    porcAlcance = (masch.totNeta / metaMaschN1) * 100;
    porcComis = masch.totNeta >= metaMaschN2 ? 0.30 : (masch.totNeta >= metaMaschN1 ? 0.20 : 0.10);
    montoComis = Math.round(masch.totNeta * (porcComis / 100));
  } else {
    porcComis = vData.neta >= metaN2 ? 0.90 : (vData.neta >= metaPrevista ? 0.60 : 0.30);
    montoComis = Math.round(vData.neta * (porcComis / 100));
  }

  liquidaciones.push({
    periodo,
    sucursal_codigo: 'MASCHWITZ',
    colab_id: s.colab_id,
    nombre: s.nombre,
    rol: s.rol,
    venta_bruta: vData.bruto,
    notas_credito: vData.nc,
    venta_neta: vData.neta,
    objetivo_previsto: metaPrevista,
    porc_alcance: Math.round(porcAlcance * 100) / 100,
    porc_comision: porcComis,
    monto_comision: montoComis,
    monto_plus_caja: 0,
    monto_pozo: 0,
    total_liquidado: montoComis,
    estado_premio: porcAlcance >= 90 ? `⭐ Estrella del Mes (${Math.round(porcAlcance)}%)` : 'Desempeño estándar',
    estado: 'borrador'
  });
});

// 2. PROYECCIÓN AUTOMÁTICA DE NUEVOS OBJETIVOS (SALTO DUX + HORAS REALES APP)
const nuevosObjetivos = [];

// Proyectar Meta Local N1
const nuevoN1Tom = Math.round((tom.totNeta * duxData.saltoEstacionalTom) / 1000) * 1000;
const nuevoN2Tom = Math.round((nuevoN1Tom * 1.18) / 1000) * 1000;
const nuevoN1Masch = Math.round((masch.totNeta * duxData.saltoEstacionalMasch) / 1000) * 1000;
const nuevoN2Masch = Math.round((nuevoN1Masch * 1.18) / 1000) * 1000;

// Helper para obtener horas netas trabajadas desde la App
function getHorasNetas(cId, fallbackHs) {
  const rec = horasApp.find(h => h.colab_id === cId);
  if (!rec) return fallbackHs;
  const base = Number(rec.horas_base || 0);
  const vac = Number(rec.vacaciones_hs || 0);
  const adic = Number(rec.adicional_hs || 0);
  return Math.max(0, base - vac + adic);
}

// Reparto TOM ponderado con horas reales de la App
const hsSofi = getHorasNetas('c-sofi', 192) * 0.65; // ratio Sofi 65%
const hsEsme = getHorasNetas('c-esme', 160);
const hsCande = getHorasNetas('c-cande', 72);
const hsAnto = getHorasNetas('c-anto', 96);
const hsMartu = getHorasNetas('c-martu', 42);
const sumHsTom = hsSofi + hsEsme + hsCande + hsAnto + hsMartu;

nuevosObjetivos.push({ periodo: nextPeriod, sucursal_codigo: 'TOM', colab_id: 'TOTAL_LOCAL', nombre_concepto: 'TOTAL LOCAL', rol: 'Local', horas_semanales: 138, objetivo_nivel_1: nuevoN1Tom, objetivo_nivel_2: nuevoN2Tom, pozo_grupal: 0, estado: 'borrador' });
nuevosObjetivos.push({ periodo: nextPeriod, sucursal_codigo: 'TOM', colab_id: 'c-esme', nombre_concepto: 'Esme', rol: 'Semi-Encargada', horas_semanales: 42, objetivo_nivel_1: Math.round((nuevoN1Tom * hsEsme / sumHsTom) / 1000) * 1000, objetivo_nivel_2: Math.round((nuevoN2Tom * hsEsme / sumHsTom) / 1000) * 1000, pozo_grupal: 0, estado: 'borrador' });
nuevosObjetivos.push({ periodo: nextPeriod, sucursal_codigo: 'TOM', colab_id: 'c-anto', nombre_concepto: 'Antonella', rol: 'Vendedora', horas_semanales: 24, objetivo_nivel_1: Math.round((nuevoN1Tom * hsAnto / sumHsTom) / 1000) * 1000, objetivo_nivel_2: Math.round((nuevoN2Tom * hsAnto / sumHsTom) / 1000) * 1000, pozo_grupal: 0, estado: 'borrador' });
nuevosObjetivos.push({ periodo: nextPeriod, sucursal_codigo: 'TOM', colab_id: 'c-cande', nombre_concepto: 'Candela', rol: 'Vendedora', horas_semanales: 24, objetivo_nivel_1: Math.round((nuevoN1Tom * hsCande / sumHsTom) / 1000) * 1000, objetivo_nivel_2: Math.round((nuevoN2Tom * hsCande / sumHsTom) / 1000) * 1000, pozo_grupal: 0, estado: 'borrador' });
nuevosObjetivos.push({ periodo: nextPeriod, sucursal_codigo: 'TOM', colab_id: 'c-sofi', nombre_concepto: 'Sofía', rol: 'Encargada', horas_semanales: 36, objetivo_nivel_1: Math.round((nuevoN1Tom * hsSofi / sumHsTom) / 1000) * 1000, objetivo_nivel_2: Math.round((nuevoN2Tom * hsSofi / sumHsTom) / 1000) * 1000, pozo_grupal: 0, estado: 'borrador' });
nuevosObjetivos.push({ periodo: nextPeriod, sucursal_codigo: 'TOM', colab_id: 'c-martu', nombre_concepto: 'Martu P.', rol: 'Vendedora', horas_semanales: 12, objetivo_nivel_1: Math.round((nuevoN1Tom * hsMartu / sumHsTom) / 1000) * 1000, objetivo_nivel_2: Math.round((nuevoN2Tom * hsMartu / sumHsTom) / 1000) * 1000, pozo_grupal: 0, estado: 'borrador' });

// Reparto Maschwitz
