const hsJuli = getHorasNetas('c-juli', 66);
const hsCami = getHorasNetas('c-cami', 88);
const hsMartuMasch = getHorasNetas('c-martu_masch', 44);
const sumHsMasch = hsFlavia + hsJuli + hsCami + hsMartuMasch;

nuevosObjetivos.push({ periodo: nextPeriod, sucursal_codigo: 'MASCHWITZ', colab_id: 'TOTAL_LOCAL', nombre_concepto: 'TOTAL LOCAL', rol: 'Local', horas_semanales: 77, objetivo_nivel_1: nuevoN1Masch, objetivo_nivel_2: nuevoN2Masch, pozo_grupal: 0, estado: 'borrador' });
nuevosObjetivos.push({ periodo: nextPeriod, sucursal_codigo: 'MASCHWITZ', colab_id: 'c-flavia', nombre_concepto: 'Flavia', rol: 'Encargada', horas_semanales: 27.5, objetivo_nivel_1: Math.round((nuevoN1Masch * hsFlavia / sumHsMasch) / 1000) * 1000, objetivo_nivel_2: Math.round((nuevoN2Masch * hsFlavia / sumHsMasch) / 1000) * 1000, pozo_grupal: 0, estado: 'borrador' });
nuevosObjetivos.push({ periodo: nextPeriod, sucursal_codigo: 'MASCHWITZ', colab_id: 'c-juli', nombre_concepto: 'Julieta', rol: 'Vendedora', horas_semanales: 22, objetivo_nivel_1: Math.round((nuevoN1Masch * hsJuli / sumHsMasch) / 1000) * 1000, objetivo_nivel_2: Math.round((nuevoN2Masch * hsJuli / sumHsMasch) / 1000) * 1000, pozo_grupal: 0, estado: 'borrador' });
nuevosObjetivos.push({ periodo: nextPeriod, sucursal_codigo: 'MASCHWITZ', colab_id: 'c-cami', nombre_concepto: 'Cami Vera', rol: 'Vendedora', horas_semanales: 22, objetivo_nivel_1: Math.round((nuevoN1Masch * hsCami / sumHsMasch) / 1000) * 1000, objetivo_nivel_2: Math.round((nuevoN2Masch * hsCami / sumHsMasch) / 1000) * 1000, pozo_grupal: 0, estado: 'borrador' });
