const totComisiones = liquidaciones.reduce((acc, l) => acc + l.total_liquidado, 0);

// Mensaje Telegram para Juan
const msgTelegram = `📊 <b>CIERRE COMERCIAL DUX — ${periodo}</b>\n\n` +
`🏢 <b>TOM:</b> $${tom.totNeta.toLocaleString('es-AR')} neto\n` +
`🏢 <b>MASCHWITZ:</b> $${masch.totNeta.toLocaleString('es-AR')} neto\n` +
`💰 <b>Comisiones Calculadas:</b> $${totComisiones.toLocaleString('es-AR')}\n\n` +
`🎯 <b>Nuevos Objetivos (${nextPeriod}):</b> Proyectados con Salto Histórico Dux y Horas Netas de la App.\n\n` +
`⚠️ <i>Estado: BORRADOR (Requiere tu aprobación).</i>\n` +
`👉 <a href="https://juanoviedo1987-droid.github.io/NAZARIA-RRHH/">Revisar y Aprobar en la App</a>`;

return [{
  json: {
    periodo,
    nextPeriod,
    liquidaciones,
    nuevosObjetivos,
    msgTelegram
  }
}];
